    "text": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\u041F\u0440\u0438\u0439\u043C\u0430\u0454 \u043E\u0434\u043D\u043E\u0440\u044F\u0434\u043A\u043E\u0432\u0438\u0439 \u0442\u0435\u043A\u0441\u0442." } },
    "longText": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\u041F\u0440\u0438\u0439\u043C\u0430\u0454 \u0431\u0430\u0433\u0430\u0442\u043E\u0440\u044F\u0434\u043A\u043E\u0432\u0438\u0439 \u0442\u0435\u043A\u0441\u0442. \u042F\u043A\u0449\u043E \u0443\u0432\u0456\u043C\u043A\u043D\u0435\u043D\u043E \u0444\u043E\u0440\u043C\u0430\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u0437\u0431\u0430\u0433\u0430\u0447\u0435\u043D\u043E\u0433\u043E \u0442\u0435\u043A\u0441\u0442\u0443, \u0432\u0438 \u043C\u043E\u0436\u0435\u0442\u0435 \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0432\u0430\u0442\u0438 markdown \u0434\u043B\u044F \u0444\u043E\u0440\u043C\u0430\u0442\u0443\u0432\u0430\u043D\u043D\u044F \u0442\u0435\u043A\u0441\u0442\u0443." } },
    "linkRow": { "t": 0, "b": { "t": 2, "i": [{ "t": 3, "v": "\u041F\u0440\u0438\u0439\u043C\u0430\u0454 \u043C\u0430\u0441\u0438\u0432, \u0449\u043E \u043C\u0456\u0441\u0442\u0438\u0442\u044C \u0456\u0434\u0435\u043D\u0442\u0438\u0444\u0456\u043A\u0430\u0442\u043E\u0440\u0438 \u0430\u0431\u043E \u0442\u0435\u043A\u0441\u0442\u043E\u0432\u0456 \u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u0433\u043E \u043F\u043E\u043B\u044F \u043F\u043E\u0432'\u044F\u0437\u0430\u043D\u0438\u0445 \u0440\u044F\u0434\u043A\u0456\u0432 \u0437 \u0442\u0430\u0431\u043B\u0438\u0446\u0456 id " }, { "t": 4, "k": "table" }, { "t": 3, "v": ". \u0423\u0441\u0456 \u0456\u0434\u0435\u043D\u0442\u0438\u0444\u0456\u043A\u0430\u0442\u043E\u0440\u0438 \u043F\u043E\u0432\u0438\u043D\u043D\u0456 \u043D\u0430\u0434\u0430\u0432\u0430\u0442\u0438\u0441\u044F \u0449\u043E\u0440\u0430\u0437\u0443 \u043F\u0440\u0438 \u043E\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u0456 \u0437\u0432'\u044F\u0437\u043A\u0456\u0432. \u042F\u043A\u0449\u043E \u043D\u0430\u0434\u0430\u043D\u043E \u043F\u043E\u0440\u043E\u0436\u043D\u0456\u0439 \u043C\u0430\u0441\u0438\u0432, \u0443\u0441\u0456 \u0437\u0432'\u044F\u0437\u043A\u0438 \u0431\u0443\u0434\u0443\u0442\u044C \u0432\u0438\u0434\u0430\u043B\u0435\u043D\u0456. \u0423 \u0432\u0438\u043F\u0430\u0434\u043A\u0443 \u0442\u0435\u043A\u0441\u0442\u043E\u0432\u043E\u0433\u043E \u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F \u0437\u0430\u043C\u0456\u0441\u0442\u044C \u0456\u0434\u0435\u043D\u0442\u0438\u0444\u0456\u043A\u0430\u0442\u043E\u0440\u0430 \u0431\u0443\u0434\u0435 \u0437\u0434\u0456\u0439\u0441\u043D\u0435\u043D\u043E \u043F\u043E\u0448\u0443\u043A \u0440\u044F\u0434\u043A\u0430 \u0437 \u0432\u0456\u0434\u043F\u043E\u0432\u0456\u0434\u043D\u0438\u043C \u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F\u043C \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u0433\u043E \u043F\u043E\u043B\u044F. \u042F\u043A\u0449\u043E \u0437\u043D\u0430\u0439\u0434\u0435\u043D\u043E \u0431\u0456\u043B\u044C\u0448\u0435 \u043E\u0434\u043D\u043E\u0433\u043E \u0437\u0431\u0456\u0433\u0443, \u0432\u0438\u0431\u0438\u0440\u0430\u0454\u0442\u044C\u0441\u044F \u043F\u0435\u0440\u0448\u0438\u0439 \u0443 \u043F\u043E\u0440\u044F\u0434\u043A\u0443 \u0442\u0430\u0431\u043B\u0438\u0446\u0456. \u0412\u0438 \u043C\u043E\u0436\u0435\u0442\u0435 \u043D\u0430\u0434\u0456\u0441\u043B\u0430\u0442\u0438 \u0440\u044F\u0434\u043E\u043A \u0437 \u0456\u043C\u0435\u043D\u0430\u043C\u0438, \u0440\u043E\u0437\u0434\u0456\u043B\u0435\u043D\u0438\u043C\u0438 \u043A\u043E\u043C\u043E\u044E, \u0443 \u0446\u044C\u043E\u043C\u0443 \u0432\u0438\u043F\u0430\u0434\u043A\u0443 \u0440\u044F\u0434\u043E\u043A \u043F\u0435\u0440\u0435\u0442\u0432\u043E\u0440\u044E\u0454\u0442\u044C\u0441\u044F \u043D\u0430 \u043C\u0430\u0441\u0438\u0432 \u0456\u043C\u0435\u043D \u0440\u044F\u0434\u043A\u0456\u0432. \u0412\u0438 \u0442\u0430\u043A\u043E\u0436 \u043C\u043E\u0436\u0435\u0442\u0435 \u043D\u0430\u0434\u0456\u0441\u043B\u0430\u0442\u0438 \u043B\u0438\u0448\u0435 \u043E\u0434\u0438\u043D ID \u0440\u044F\u0434\u043A\u0430." }] } },
