    "stddevPopDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\u041E\u0431\u0447\u0438\u0441\u043B\u044E\u0454 \u0441\u0442\u0430\u043D\u0434\u0430\u0440\u0442\u043D\u0435 \u0432\u0456\u0434\u0445\u0438\u043B\u0435\u043D\u043D\u044F \u0433\u0435\u043D\u0435\u0440\u0430\u043B\u044C\u043D\u043E\u0457 \u0441\u0443\u043A\u0443\u043F\u043D\u043E\u0441\u0442\u0456 \u0437\u043D\u0430\u0447\u0435\u043D\u044C \u0456 \u043F\u043E\u0432\u0435\u0440\u0442\u0430\u0454 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442. \u0421\u0442\u0430\u043D\u0434\u0430\u0440\u0442\u043D\u0435 \u0432\u0456\u0434\u0445\u0438\u043B\u0435\u043D\u043D\u044F \u0433\u0435\u043D\u0435\u0440\u0430\u043B\u044C\u043D\u043E\u0457 \u0441\u0443\u043A\u0443\u043F\u043D\u043E\u0441\u0442\u0456 \u0441\u043B\u0456\u0434 \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0432\u0430\u0442\u0438, \u043A\u043E\u043B\u0438 \u043D\u0430\u0434\u0430\u043D\u0456 \u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F \u043C\u0456\u0441\u0442\u044F\u0442\u044C \u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F \u0434\u043B\u044F \u043A\u043E\u0436\u043D\u043E\u0433\u043E \u0435\u043B\u0435\u043C\u0435\u043D\u0442\u0430 \u0434\u0430\u043D\u0438\u0445 \u0443 \u0441\u0443\u043A\u0443\u043F\u043D\u043E\u0441\u0442\u0456." } },
    "stddevSampleDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\u041E\u0431\u0447\u0438\u0441\u043B\u044E\u0454 \u0432\u0438\u0431\u0456\u0440\u043A\u043E\u0432\u0435 \u0441\u0442\u0430\u043D\u0434\u0430\u0440\u0442\u043D\u0435 \u0432\u0456\u0434\u0445\u0438\u043B\u0435\u043D\u043D\u044F \u0437\u043D\u0430\u0447\u0435\u043D\u044C \u0456 \u043F\u043E\u0432\u0435\u0440\u0442\u0430\u0454 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442. \u0412\u0438\u0431\u0456\u0440\u043A\u043E\u0432\u0435 \u0432\u0456\u0434\u0445\u0438\u043B\u0435\u043D\u043D\u044F \u0441\u043B\u0456\u0434 \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0432\u0430\u0442\u0438, \u043A\u043E\u043B\u0438 \u043D\u0430\u0434\u0430\u043D\u0456 \u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F \u0454 \u043B\u0438\u0448\u0435 \u0434\u043B\u044F \u0432\u0438\u0431\u0456\u0440\u043A\u0438 \u0430\u0431\u043E \u043F\u0456\u0434\u043C\u043D\u043E\u0436\u0438\u043D\u0438 \u0437\u043D\u0430\u0447\u0435\u043D\u044C \u0431\u0430\u0437\u043E\u0432\u043E\u0457 \u0441\u0443\u043A\u0443\u043F\u043D\u043E\u0441\u0442\u0456." } },
    "varianceSampleDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\u041E\u0431\u0447\u0438\u0441\u043B\u044E\u0454 \u0432\u0438\u0431\u0456\u0440\u043A\u043E\u0432\u0443 \u0434\u0438\u0441\u043F\u0435\u0440\u0441\u0456\u044E \u0437\u043D\u0430\u0447\u0435\u043D\u044C \u0456 \u043F\u043E\u0432\u0435\u0440\u0442\u0430\u0454 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442. \u0412\u0438\u0431\u0456\u0440\u043A\u043E\u0432\u0443 \u0434\u0438\u0441\u043F\u0435\u0440\u0441\u0456\u044E \u0441\u043B\u0456\u0434 \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0432\u0430\u0442\u0438, \u043A\u043E\u043B\u0438 \u043D\u0430\u0434\u0430\u043D\u0456 \u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F \u0454 \u043B\u0438\u0448\u0435 \u0434\u043B\u044F \u0432\u0438\u0431\u0456\u0440\u043A\u0438 \u0430\u0431\u043E \u043F\u0456\u0434\u043C\u043D\u043E\u0436\u0438\u043D\u0438 \u0437\u043D\u0430\u0447\u0435\u043D\u044C \u0431\u0430\u0437\u043E\u0432\u043E\u0457 \u0441\u0443\u043A\u0443\u043F\u043D\u043E\u0441\u0442\u0456." } },
    "variancePopDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\u041E\u0431\u0447\u0438\u0441\u043B\u044E\u0454 \u0434\u0438\u0441\u043F\u0435\u0440\u0441\u0456\u044E \u0433\u0435\u043D\u0435\u0440\u0430\u043B\u044C\u043D\u043E\u0457 \u0441\u0443\u043A\u0443\u043F\u043D\u043E\u0441\u0442\u0456 \u0437\u043D\u0430\u0447\u0435\u043D\u044C \u0456 \u043F\u043E\u0432\u0435\u0440\u0442\u0430\u0454 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442. \u0414\u0438\u0441\u043F\u0435\u0440\u0441\u0456\u044E \u0433\u0435\u043D\u0435\u0440\u0430\u043B\u044C\u043D\u043E\u0457 \u0441\u0443\u043A\u0443\u043F\u043D\u043E\u0441\u0442\u0456 \u0441\u043B\u0456\u0434 \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0432\u0430\u0442\u0438, \u043A\u043E\u043B\u0438 \u043D\u0430\u0434\u0430\u043D\u0456 \u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F \u043C\u0456\u0441\u0442\u044F\u0442\u044C \u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F \u0434\u043B\u044F \u043A\u043E\u0436\u043D\u043E\u0433\u043E \u0435\u043B\u0435\u043C\u0435\u043D\u0442\u0430 \u0434\u0430\u043D\u0438\u0445 \u0443 \u0441\u0443\u043A\u0443\u043F\u043D\u043E\u0441\u0442\u0456." } },
